"""Generated by solo-to-scale; edit `templates/tools/control.py` in the plugin, then run upgrade.

Pause, resume and wake agents from your phone. One issue labelled `agent-controls` holds the founder's commands:
  /pause <role> [reason]    that role's heartbeat stops at its next start, until /resume
  /pause all [reason]       every role stops
  /resume <role> | all
  /wake <role> | all        run that role now instead of at the next check, skipping its idle and retry waits
Only a founder's own comment counts (founder/gates.json `founders`, else the repo owner); the latest command for
a role wins. Pausing is never gated. Resuming a role whose budget is spent still needs the budget approval. A wake
never lifts a pause, turns a heartbeat on or adds budget: it only starts a run the autopilot would allow.

  python tools/control.py status            # which roles are paused, and why
  python tools/control.py issue             # the control issue's link (created when missing)

Fails closed: `heartbeat.py start` stops a role when this can't be read.
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import tickets  # noqa: E402

LABEL = "agent-controls"
TITLE = "Agent controls: /pause, /resume and /wake"
COMMAND = re.compile(r"^\s*/(pause|resume|wake)[ \t]+(?:role:)?([a-z][a-z0-9-]*)\b[ \t]*(.*)$", re.IGNORECASE | re.MULTILINE)
BODY = ("Reply here from any device to pause, resume or wake an AI role. Only the founder's own comments count.\n\n"
        "- `/pause <role> [reason]`: that role's heartbeat stops at its next start, until `/resume <role>`\n"
        "- `/pause all [reason]` and `/resume all`\n"
        "- `/wake <role>` or `/wake all`: run now instead of at the next check\n\n"
        "Pausing is never gated. Resuming a role whose budget is spent still needs the budget approval. A wake never "
        "lifts a pause or adds budget.")
WAKE_HOURS = 2  # a wake nobody acted on by then (cap reached, budget spent) is dropped, so it never fires late


def state(comments: list[dict[str, Any]], founder_logins: set[str]) -> dict[str, Any]:
    """{'all': reason or None, 'roles': {role: reason}}: the founder's latest command per role, in order."""
    every: str | None = None
    roles: dict[str, str] = {}
    for c in comments:
        if (c.get("user") or {}).get("login", "").lower() not in founder_logins:
            continue
        for verb, who, why in COMMAND.findall(c.get("body") or ""):
            verb, who, why = verb.lower(), who.lower(), why.strip()[:200]
            if verb == "wake":
                continue
            if who == "all":
                every = (why or "paused") if verb == "pause" else None
                if verb == "resume":
                    roles.clear()
            elif verb == "pause":
                roles[who] = why or "paused"
            else:
                roles.pop(who, None)
    return {"all": every, "roles": roles}


def wakes(comments: list[dict[str, Any]], founder_logins: set[str]) -> dict[str, str]:
    """{role or 'all': when the founder's latest /wake for it was posted (ISO time)}."""
    out: dict[str, str] = {}
    for c in comments:
        if (c.get("user") or {}).get("login", "").lower() not in founder_logins:
            continue
        for verb, who, _ in COMMAND.findall(c.get("body") or ""):
            if verb.lower() == "wake":
                out[who.lower()] = str(c.get("created_at") or "")
    return out


def _when(iso: Any) -> dt.datetime | None:
    try:
        t = dt.datetime.fromisoformat(str(iso).replace("Z", "+00:00"))
    except ValueError:
        return None
    return t if t.tzinfo else t.replace(tzinfo=dt.timezone.utc)


def woken(st: dict[str, Any], role: str, runs: list[dict[str, Any]], now: dt.datetime) -> str:
    """When the founder asked this role to wake, if no run of it has ended since and the ask is under WAKE_HOURS old;
    else empty. A run's cost entry is written when it ends, so the run a wake starts is the one that spends it."""
    asks = [t for t in (_when((st.get("wakes") or {}).get(k)) for k in (role, "all")) if t]
    if not asks:
        return ""
    at = max(asks)
    if (now - at).total_seconds() > WAKE_HOURS * 3600 or at > now + dt.timedelta(minutes=5):
        return ""
    for e in runs:
        t = _when(e.get("at"))
        if e.get("role") == role and t and t >= at:
            return ""
    return at.strftime("%Y-%m-%dT%H:%M:%SZ")


def paused(st: dict[str, Any], role: str) -> str | None:
    """Why the role is paused, or None when it may run."""
    return st["roles"].get(role) or st["all"]


def issue(hub: tickets.Hub, create: bool) -> dict[str, Any] | None:
    found = sorted(hub.tickets("open", LABEL), key=lambda i: i["number"])
    if found or not create:
        return found[0] if found else None
    return hub.api("issues", "-X", "POST", payload={"title": TITLE, "body": BODY, "labels": [LABEL]})


def read(hub: tickets.Hub, root: Path) -> dict[str, Any]:
    """The control state and the issue's link; no issue means nothing is paused."""
    found = issue(hub, create=False)
    if not found:
        return {"all": None, "roles": {}, "wakes": {}, "url": ""}
    comments: list[dict[str, Any]] = []
    for page in range(1, 11):
        got = hub.api(f"issues/{found['number']}/comments?per_page=100&page={page}") or []
        comments += got
        if len(got) < 100:
            break
    who = approval.founders(approval.policy(root), hub.repo)
    return {**state(comments, who), "wakes": wakes(comments, who), "url": found.get("html_url", ""), "number": found["number"]}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Pause, resume and wake agents")
    ap.add_argument("cmd", choices=("status", "issue"))
    ap.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    a = ap.parse_args(argv)
    repo = approval.repo_name(a.root)
    if not repo:
        print("can't tell which GitHub repo this is")
        return 5
    hub = tickets.Hub(repo)
    try:
        if a.cmd == "issue":
            found = issue(hub, create=True)
            print(f"#{found['number']} {found.get('html_url', '')}")
            return 0
        st = read(hub, a.root)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__})")
        return 5
    if st["all"]:
        print(f"ALL roles paused: {st['all']}")
    for role, why in sorted(st["roles"].items()):
        print(f"role:{role} paused: {why}")
    if not st["all"] and not st["roles"]:
        print("No role is paused.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
